//
//  GeneratedCode.swift
//  SwiftStatsCore
//
//  Which files are generated (PRD D8): a path matching a `generated` glob,
//  or a known header in the file's leading comment. Being generated changes
//  no measurement; it marks the file, and its tests stay out of ratios.
//

import SwiftSyntax

/// Recognises generated files.
enum GeneratedCode {
    /// The globs used when `.swiftstats.yml` gives no `generated` key.
    static let defaultGlobs = ["**/*.generated.swift", "**/*.pb.swift", "**/*.grpc.swift", "**/Generated/**"]

    /// Text that marks a generated file when its leading comment holds it.
    static let headers = [
        "Auto-generated by `swift-infer",
        "GENERATED by PropertyLawDiscoveryPlugin",
        "Generated using Sourcery",
        "Generated using SwiftGen",
        "DO NOT EDIT"
    ]

    /// Whether `file` matches one of `globs` or carries a known header.
    static func isGenerated(_ file: ParsedFile, globs: [GlobPattern]) -> Bool {
        globs.contains { $0.matches(file.path) } || hasHeader(file.tree)
    }

    /// Whether the comments before the file's first token hold a known header.
    static func hasHeader(_ tree: SourceFileSyntax) -> Bool {
        let trivia = tree.firstToken(viewMode: .sourceAccurate)?.leadingTrivia ?? []
        return trivia.contains { piece in
            switch piece {
            case .lineComment(let text), .blockComment(let text), .docLineComment(let text), .docBlockComment(let text):
                return headers.contains { text.contains($0) }

            default:
                return false
            }
        }
    }
}
